    "components" : {
      "schemas" : {
        "UpdateScheduleItemRequest" : {
          "type" : "object",
          "description" : "Запрос на полное обновление (PUT) шаблона пары; groupId/semesterId неизменяемы (D-09)",
          "properties" : {
            "subjectId" : {
              "type" : "integer",
              "format" : "int64",
              "description" : "ID предмета",
              "example" : 42
            },
            "dayOfWeek" : {
              "type" : "integer",
              "format" : "int32",
              "description" : "День недели: 1 — понедельник, 7 — воскресенье",
              "example" : 1,
              "maximum" : 7,
              "minimum" : 1
            },
            "lessonNumber" : {
              "type" : "integer",
              "format" : "int32",
              "description" : "Номер пары в дне (1..8)",
              "example" : 2,
              "maximum" : 8,
              "minimum" : 1
            },
            "startTime" : {
              "type" : "string",
              "description" : "Время начала пары",
              "example" : "10:30:00"
            },
            "endTime" : {
              "type" : "string",
              "description" : "Время окончания пары",
              "example" : "12:00:00"
            },
            "weekType" : {
              "type" : "string",
              "description" : "Тип недели: ODD — 1-я (ISO чётная), EVEN — 2-я (ISO нечётная)",
              "enum" : [ "ALL", "ODD", "EVEN" ],
              "example" : "EVEN"
            },
